[package]
name = "jiter-python"
version = {workspace = true}
edition = {workspace = true}
authors = {workspace = true}
license = {workspace = true}
keywords = {workspace = true}
categories = {workspace = true}
homepage = {workspace = true}
repository = {workspace = true}
rust-version = { workspace = true }

[dependencies]
pyo3 = { workspace = true, features = ["num-bigint"] }
jiter = { path = "../jiter", features = ["python", "num-bigint"] }

[features]
# make extensions visible to cargo vendor
extension-module = []

[lib]
name = "jiter_python"
crate-type = ["cdylib", "rlib"]

[lints.clippy]
dbg_macro = "deny"
print_stdout = "deny"
print_stderr = "deny"
# in general we lint against the pedantic group, but we will whitelist
# certain lints which we don't want to enforce (for now)
pedantic = { level = "deny", priority = -1 }
missing_errors_doc = "allow"
must_use_candidate = "allow"

use pyo3::prelude::*;
use pyo3::types::PyString;

use jiter::{JsonValue, PythonParse, StringCacheMode, pystring_ascii_new};

#[cfg(feature = "num-bigint")]
#[test]
fn test_to_py_object_numeric() {
    let value = JsonValue::parse(
        br#"  { "int": 1, "bigint": 123456789012345678901234567890, "float": 1.2}  "#,
        false,
    )
    .unwrap();
    Python::attach(|py| {
        let python_value = value.into_pyobject(py).unwrap();
        let string = python_value.to_string();
        assert_eq!(
            string,
            "{'int': 1, 'bigint': 123456789012345678901234567890, 'float': 1.2}"
        );
    });
}

#[test]
fn test_to_py_object_other() {
    let value = JsonValue::parse(
        br#"["string", "\u00a3", true, false, null, NaN, Infinity, -Infinity]"#,
        true,
    )
    .unwrap();
    Python::attach(|py| {
        let python_value = value.into_pyobject(py).unwrap();
        let string = python_value.to_string();
        assert_eq!(string, "['string', '£', True, False, None, nan, inf, -inf]");
    });
}

#[test]
fn test_cache_into() {
    Python::attach(|py| {
        let c: StringCacheMode = true.into_pyobject(py).unwrap().extract().unwrap();
        assert!(matches!(c, StringCacheMode::All));

        let c: StringCacheMode = false.into_pyobject(py).unwrap().extract().unwrap();
        assert!(matches!(c, StringCacheMode::None));

        let c: StringCacheMode = PyString::new(py, "all").extract().unwrap();
        assert!(matches!(c, StringCacheMode::All));

        let c: StringCacheMode = PyString::new(py, "keys").extract().unwrap();
        assert!(matches!(c, StringCacheMode::Keys));

        let c: StringCacheMode = PyString::new(py, "none").extract().unwrap();
        assert!(matches!(c, StringCacheMode::None));

        let e = PyString::new(py, "wrong").extract::<StringCacheMode>().unwrap_err();
        assert_eq!(
            e.to_string(),
            "ValueError: Invalid string cache mode, should be `'all'`, '`keys`', `'none`' or a `bool`"
        );
        let e = 123i32
            .into_pyobject(py)
            .unwrap()
            .extract::<StringCacheMode>()
            .unwrap_err();
        assert_eq!(
            e.to_string(),
            "TypeError: Invalid string cache mode, should be `'all'`, '`keys`', `'none`' or a `bool`"
        );
    });
}

#[test]
fn test_pystring_ascii_new() {
    let json = "100abc";
    Python::attach(|py| {
        // SAFETY: `json` contains only ASCII characters.
        let s = unsafe { pystring_ascii_new(py, json) };
        assert_eq!(s.to_string(), "100abc");
    });
}

#[test]
fn test_python_parse_default() {
    Python::attach(|py| {
        let v = PythonParse::default().python_parse(py, b"[123]").unwrap();
        assert_eq!(v.to_string(), "[123]");
    });
}

use std::collections::BTreeMap;

use serde::Deserialize;

use jiter::serde::{Error, JiterDeserializer, from_slice, from_str};

fn de_f64_inf_nan(s: &str) -> f64 {
    let mut de = JiterDeserializer::new(s.as_bytes()).with_allow_inf_nan();
    let v = f64::deserialize(&mut de).unwrap();
    de.finish().unwrap();
    v
}

fn de_value_inf_nan(s: &str) -> serde_json::Value {
    let mut de = JiterDeserializer::new(s.as_bytes()).with_allow_inf_nan();
    let v = serde_json::Value::deserialize(&mut de).unwrap();
    de.finish().unwrap();
    v
}

#[test]
fn primitives() {
    assert!(from_str::<bool>("true").unwrap());
    assert_eq!(from_str::<i64>("-42").unwrap(), -42);
    assert_eq!(from_str::<u64>("42").unwrap(), 42);
    assert!((from_str::<f64>("2.5").unwrap() - 2.5).abs() < f64::EPSILON);
    assert_eq!(from_str::<String>(r#""hello""#).unwrap(), "hello");
    assert_eq!(from_str::<Option<i64>>("null").unwrap(), None);
    assert_eq!(from_str::<Option<i64>>("5").unwrap(), Some(5));
    assert_eq!(from_str::<()>("null").unwrap(), ());
}

#[test]
fn vecs_and_maps() {
    assert_eq!(from_str::<Vec<i64>>("[1, 2, 3]").unwrap(), vec![1, 2, 3]);
    assert_eq!(from_str::<Vec<i64>>("[]").unwrap(), Vec::<i64>::new());

    let map: BTreeMap<String, i64> = from_str(r#"{"a": 1, "b": 2}"#).unwrap();
    assert_eq!(map, BTreeMap::from([("a".to_string(), 1), ("b".to_string(), 2)]));

    // integer keys (parsed from the key string)
    let map: BTreeMap<u32, String> = from_str(r#"{"1": "one", "2": "two"}"#).unwrap();
    assert_eq!(map, BTreeMap::from([(1, "one".to_string()), (2, "two".to_string())]));
}

#[derive(Deserialize, PartialEq, Debug)]
struct Person<'a> {
    name: &'a str,
    age: u8,
    phones: Vec<&'a str>,
}

#[test]
fn borrowed_struct() {
    let data = r#"{"name": "John Doe", "age": 43, "phones": ["+44 111", "+44 222"]}"#;
    let person: Person = from_str(data).unwrap();
    assert_eq!(
        person,
        Person {
            name: "John Doe",
            age: 43,
            phones: vec!["+44 111", "+44 222"],
        }
    );
}

#[test]
fn zero_copy_borrowed_str() {
    // unescaped `&str` borrows from the input: the slice points inside the input buffer
    let data = br#""no escapes here""#;
    let s: &str = from_slice(data).unwrap();
    assert_eq!(s, "no escapes here");
    let input = data.as_ptr() as usize..(data.as_ptr() as usize + data.len());
    assert!(
        input.contains(&(s.as_ptr() as usize)),
        "string should borrow from input"
    );
}

#[test]
fn escaped_string_is_owned() {
    // escapes force decoding onto the tape; deserializing to an owned `String` works
    let s: String = from_str(r#""tab\tnewline\n""#).unwrap();
    assert_eq!(s, "tab\tnewline\n");
}

#[test]
fn borrowed_str_with_escape_errors() {
    // an escaped `&str` can't be borrowed (same as serde_json)
    let err = from_str::<&str>(r#""has \t escape""#).unwrap_err();
    assert!(matches!(err, Error::Data { .. }));
}

#[derive(Deserialize, PartialEq, Debug)]
struct Nested {
    inner: Inner,
    list: Vec<Inner>,
}

#[derive(Deserialize, PartialEq, Debug)]
struct Inner {
    value: i64,
}

#[test]
fn nested() {
    let data = r#"{"inner": {"value": 1}, "list": [{"value": 2}, {"value": 3}]}"#;
    let nested: Nested = from_str(data).unwrap();
    assert_eq!(
        nested,
        Nested {
            inner: Inner { value: 1 },
            list: vec![Inner { value: 2 }, Inner { value: 3 }],
        }
    );
}

#[derive(Deserialize, PartialEq, Debug)]
enum Shape {
    Unit,
    Newtype(i64),
    Tuple(i64, i64),
    Struct { x: i64, y: i64 },
}

#[test]
fn enums() {
    assert_eq!(from_str::<Shape>(r#""Unit""#).unwrap(), Shape::Unit);
    assert_eq!(from_str::<Shape>(r#"{"Newtype": 7}"#).unwrap(), Shape::Newtype(7));
    assert_eq!(from_str::<Shape>(r#"{"Tuple": [1, 2]}"#).unwrap(), Shape::Tuple(1, 2));
    assert_eq!(
        from_str::<Shape>(r#"{"Struct": {"x": 1, "y": 2}}"#).unwrap(),
        Shape::Struct { x: 1, y: 2 }
    );
}

#[derive(Deserialize, PartialEq, Debug)]
struct Ordered {
    a: i64,
    b: String,
    c: bool,
    #[serde(default)]
    d: Option<i64>,
}

#[test]
fn field_order_independent() {
    let declared = Ordered {
        a: 1,
        b: "two".to_string(),
        c: true,
        d: Some(4),
    };

    // declaration order
    assert_eq!(
        from_str::<Ordered>(r#"{"a": 1, "b": "two", "c": true, "d": 4}"#).unwrap(),
        declared
    );
    // fully reversed order
    assert_eq!(
        from_str::<Ordered>(r#"{"d": 4, "c": true, "b": "two", "a": 1}"#).unwrap(),
        declared
    );
    // shuffled, unknown fields interspersed, `d` omitted
    let shuffled = r#"{"c": true, "x": [1, 2, 3], "b": "two", "y": {"z": null}, "a": 1}"#;
    assert_eq!(
        from_str::<Ordered>(shuffled).unwrap(),
        Ordered {
            a: 1,
            b: "two".to_string(),
            c: true,
            d: None,
        }
    );
}

#[test]
fn skips_unknown_fields() {
    // unknown fields are skipped
    let data = r#"{"value": 5, "unknown": [1, 2, {"deep": "nested"}], "more": null}"#;
    let inner: Inner = from_str(data).unwrap();
    assert_eq!(inner, Inner { value: 5 });
}

#[test]
fn trailing_data_errors() {
    assert!(from_str::<i64>("1 2").is_err());
    assert!(from_str::<Vec<i64>>("[1, 2] extra").is_err());
}

#[test]
fn wrong_type_errors() {
    let err = from_str::<i64>(r#""not a number""#).unwrap_err();
    // string where i64 expected
    assert!(matches!(err, Error::Data { .. }));
}

#[test]
fn type_error_carries_real_position() {
    #[derive(Deserialize, Debug)]
    #[allow(dead_code)]
    struct S {
        a: i64,
        b: i64,
    }
    // the error points at the offending value, not index 0
    let data = r#"{"a": 1, "b": "oops"}"#;
    let err = from_str::<S>(data).unwrap_err();
    assert!(matches!(err, Error::Data { .. }));
    assert_eq!(err.index(), Some(data.find("\"oops\"").unwrap()));
}

#[test]
fn top_level_unknown_variant_is_positioned() {
    // an unknown variant on a top-level enum is reported during variant identification and never
    // unwinds through `deserialize_any`, so the error must be positioned at the boundary rather than
    // reaching the caller as a bare, unpositioned `Message`
    let err = from_str::<Shape>(r#"{"Nope": 1}"#).unwrap_err();
    assert!(matches!(err, Error::Data { .. }), "got {err:?}");
    assert!(err.index().is_some(), "unknown-variant error should carry a position");
}

#[test]
fn error_resolves_to_line_and_column() {
    #[derive(Deserialize, Debug)]
    #[allow(dead_code)]
    struct S {
        a: i64,
        b: i64,
    }
    // error on line 3 resolves to a line/column
    let data = "{\n  \"a\": 1,\n  \"b\": \"oops\"\n}";
    let err = from_str::<S>(data).unwrap_err();
    let pos = err.get_position(data.as_bytes()).unwrap();
    assert_eq!(pos.line, 3);
    assert!(err.description(data.as_bytes()).contains("line 3 column"));
}

#[test]
fn from_slice_works() {
    let v: Vec<u8> = from_slice(b"[1, 2, 3]").unwrap();
    assert_eq!(v, vec![1, 2, 3]);
}

#[test]
fn recursion_limit_default_rejects_deep_nesting() {
    // beyond the default limit: a clean error, not a stack overflow
    let deep = format!("{}{}", "[".repeat(300), "]".repeat(300));
    let err = from_str::<serde_json::Value>(&deep).unwrap_err();
    assert!(matches!(&err, Error::Syntax(e) if e.error_type == jiter::JsonErrorType::RecursionLimitExceeded));
}

#[test]
fn recursion_limit_configurable() {
    let json = "[[[[[1]]]]]"; // 5 levels deep
    let mut de = JiterDeserializer::new(json.as_bytes()).with_recursion_limit(3);
    assert!(serde_json::Value::deserialize(&mut de).is_err());

    let mut de = JiterDeserializer::new(json.as_bytes()).with_recursion_limit(10);
    assert!(serde_json::Value::deserialize(&mut de).is_ok());
}

#[test]
fn recursion_limit_disabled_allows_deep_nesting() {
    // 300 levels exceeds the default of 200; disabling the limit deserializes it
    let deep = format!("{}1{}", "[".repeat(300), "]".repeat(300));
    let mut de = JiterDeserializer::new(deep.as_bytes()).disable_recursion_limit();
    assert!(serde_json::Value::deserialize(&mut de).is_ok());
    de.finish().unwrap();
}

#[test]
fn extra_tuple_elements_rejected() {
    // too many elements is an error, matching serde_json
    assert_eq!(from_str::<(i64, i64)>("[1, 2]").unwrap(), (1, 2));
    assert!(from_str::<(i64, i64)>("[1, 2, 3]").is_err());
    assert!(from_str::<[i64; 2]>("[1, 2, 3]").is_err());
}

#[derive(Deserialize, Debug, PartialEq)]
enum Tree {
    Leaf,
    Node(Box<Tree>),
}

#[test]
fn recursion_limit_counts_enum_wrappers() {
    let nested = r#"{"Node":{"Node":{"Node":"Leaf"}}}"#; // 3 nested Node objects
    // each enum wrapper counts toward the limit
    let mut de = JiterDeserializer::new(nested.as_bytes()).with_recursion_limit(2);
    assert!(Tree::deserialize(&mut de).is_err());
    // a generous limit accepts it
    let mut de = JiterDeserializer::new(nested.as_bytes()).with_recursion_limit(10);
    assert!(Tree::deserialize(&mut de).is_ok());
}

#[test]
fn unit_variant_object_form() {
    // serde_json accepts `{"Unit": null}` for a unit variant
    assert_eq!(from_str::<Shape>(r#"{"Unit": null}"#).unwrap(), Shape::Unit);
    // the bare-string form still works
    assert_eq!(from_str::<Shape>(r#""Unit""#).unwrap(), Shape::Unit);
    // non-null content for a unit variant is rejected
    assert!(from_str::<Shape>(r#"{"Unit": 5}"#).is_err());
}

#[test]
fn recursion_limit_applies_to_skipped_fields() {
    #[derive(Deserialize, Debug)]
    #[allow(dead_code)]
    struct S {
        keep: i64,
    }
    // a deeply-nested skipped field hits the limit; disabling it accepts it (up to the skip ceiling)
    let deep = format!(r#"{{"skip": {}1{}, "keep": 5}}"#, "[".repeat(230), "]".repeat(230));
    assert!(from_str::<S>(&deep).is_err());

    let mut de = JiterDeserializer::new(deep.as_bytes()).disable_recursion_limit();
    assert_eq!(S::deserialize(&mut de).unwrap().keep, 5);
}

#[test]
fn big_integers() {
    // fits in i128 but not i64
    let n: i128 = from_str("170141183460469231731687303715884105727").unwrap();
    assert_eq!(n, i128::MAX);

    // largest u128
    let n: u128 = from_str("340282366920938463463374607431768211455").unwrap();
    assert_eq!(n, u128::MAX);

    // exceeds i64 -> error when the target is i64
    assert!(from_str::<i64>("99999999999999999999999999999999").is_err());

    // bigger than u128 -> falls back to f64 (lossy), still deserializes as a float
    let huge = format!("1{}", "0".repeat(40)); // 1e40
    let f: f64 = from_str(&huge).unwrap();
    assert!((f - 1e40).abs() / 1e40 < 1e-10);
}

#[test]
fn big_floats() {
    let big: f64 = from_str("1e308").unwrap();
    assert!(big > 1e307 && big.is_finite());

    let small: f64 = from_str("1e-308").unwrap();
    assert!(small > 0.0 && small < 1e-307);

    // a long fractional literal round-trips to the nearest f64
    let pi: f64 = from_str("3.141592653589793238462643383279").unwrap();
    assert!((pi - std::f64::consts::PI).abs() < 1e-15);
}

#[test]
fn nan_and_infinity_rejected_by_default() {
    // not valid JSON unless explicitly allowed (matches serde_json)
    assert!(from_str::<f64>("NaN").is_err());
    assert!(from_str::<f64>("Infinity").is_err());
    assert!(from_str::<f64>("-Infinity").is_err());
}

#[test]
fn nan_and_infinity_allowed_when_enabled() {
    assert!(de_f64_inf_nan("NaN").is_nan());

    let inf = de_f64_inf_nan("Infinity");
    assert!(inf.is_infinite() && inf.is_sign_positive());

    let ninf = de_f64_inf_nan("-Infinity");
    assert!(ninf.is_infinite() && ninf.is_sign_negative());
}

#[test]
fn non_finite_into_value_becomes_string() {
    use serde_json::Value;
    // `serde_json::Value` can't hold non-finite floats; preserved as strings, not dropped to `Null`
    assert_eq!(de_value_inf_nan("Infinity"), Value::String("Infinity".into()));
    assert_eq!(de_value_inf_nan("-Infinity"), Value::String("-Infinity".into()));
    assert_eq!(de_value_inf_nan("NaN"), Value::String("NaN".into()));
    // ordinary floats remain numbers
    assert_eq!(de_value_inf_nan("2.5"), Value::from(2.5));
}

#[test]
fn non_finite_into_f64_keeps_real_value() {
    // typed f64 keeps the real non-finite value
    #[derive(Deserialize)]
    struct S {
        x: f64,
        y: f64,
    }
    let mut de = JiterDeserializer::new(br#"{"x": Infinity, "y": NaN}"#).with_allow_inf_nan();
    let s = S::deserialize(&mut de).unwrap();
    de.finish().unwrap();
    assert!(s.x.is_infinite() && s.x.is_sign_positive());
    assert!(s.y.is_nan());
}

#[test]
fn overflow_into_value_no_longer_null() {
    // 1e400 overflows to inf; into `Value` it becomes a string
    let v: serde_json::Value = from_str("1e400").unwrap();
    assert_eq!(v, serde_json::Value::String("Infinity".into()));
    // into a typed f64 it's the real infinity
    let f: f64 = from_str("1e400").unwrap();
    assert!(f.is_infinite());
}

#[test]
fn matches_serde_json() {
    #[derive(Deserialize, PartialEq, Debug)]
    struct Doc {
        id: u64,
        title: String,
        tags: Vec<String>,
        active: bool,
        score: f64,
        meta: Option<BTreeMap<String, String>>,
    }
    let data = r#"
        {
            "id": 12345,
            "title": "A \"quoted\" title",
            "tags": ["a", "b", "c"],
            "active": true,
            "score": 9.5,
            "meta": {"k": "v"}
        }"#;
    let from_jiter: Doc = from_str(data).unwrap();
    let from_serde: Doc = serde_json::from_str(data).unwrap();
    assert_eq!(from_jiter, from_serde);
}

// --- differential property tests against serde_json ---------------------------------------------
//
// We generate an arbitrary `serde_json::Value`, serialize it, then parse it back with both
// `jiter::serde` and `serde_json`, asserting the two agree. Generation is constrained to the part
// of the search space both parsers handle identically, sidestepping jiter's documented divergences:
//   * integers are bounded to `i64`, so we never hit the `i128`/`u128`/`f64` widening that differs
//     from serde_json's arbitrary-precision representation (covered by `big_integers`);
//   * floats are always finite, so we never produce `NaN`/`Infinity` (covered by the `non_finite_*`
//     and `nan_and_infinity_*` tests).

use proptest::prelude::*;
use serde_json::Value;

/// Strategy for a finite `f64` (excludes `NaN`/`±Infinity`, which `Number::from_f64` rejects).
fn finite_f64() -> impl Strategy<Value = f64> {
    prop::num::f64::NORMAL | prop::num::f64::SUBNORMAL | prop::num::f64::ZERO
}

/// Strategy for an integer both parsers decode identically.
///
/// With `num-bigint` the full `i64` range works. Without it, jiter's decoder rejects integers of 19+
/// digits even when they fit in `i64` (it accumulates in 18-digit chunks, then needs the bigint
/// path), so we keep generation within ±10^18 to stay inside the shared search space.
#[cfg(feature = "num-bigint")]
fn json_int() -> impl Strategy<Value = i64> {
    any::<i64>()
}
#[cfg(not(feature = "num-bigint"))]
fn json_int() -> impl Strategy<Value = i64> {
    -999_999_999_999_999_999_i64..=999_999_999_999_999_999_i64
}

/// Strategy for arbitrary JSON values both parsers agree on (see module note above).
fn json_value() -> impl Strategy<Value = Value> {
    let leaf = prop_oneof![
        Just(Value::Null),
        any::<bool>().prop_map(Value::Bool),
        json_int().prop_map(|i| Value::Number(i.into())),
        finite_f64().prop_map(|f| Value::Number(serde_json::Number::from_f64(f).unwrap())),
        any::<String>().prop_map(Value::String),
    ];
    leaf.prop_recursive(5, 64, 10, |inner| {
        prop_oneof![
            prop::collection::vec(inner.clone(), 0..10).prop_map(Value::Array),
            prop::collection::hash_map(any::<String>(), inner, 0..10)
                .prop_map(|m| Value::Object(m.into_iter().collect())),
        ]
    })
}

/// Compare two numbers by value rather than representation: with serde_json's `arbitrary_precision`
/// a `Number` stores its source text, so `9.5` parsed by serde_json and the same `f64` round-tripped
/// by jiter would compare unequal under `==` despite being the same number.
fn number_eq(a: &serde_json::Number, b: &serde_json::Number) -> bool {
    if let (Some(x), Some(y)) = (a.as_i64(), b.as_i64()) {
        return x == y;
    }
    if let (Some(x), Some(y)) = (a.as_u64(), b.as_u64()) {
        return x == y;
    }
    matches!((a.as_f64(), b.as_f64()), (Some(x), Some(y)) if x == y)
}

/// Structural equality with by-value number comparison (see [`number_eq`]).
fn json_eq(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Null, Value::Null) => true,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::String(x), Value::String(y)) => x == y,
        (Value::Number(x), Value::Number(y)) => number_eq(x, y),
        (Value::Array(x), Value::Array(y)) => x.len() == y.len() && x.iter().zip(y).all(|(a, b)| json_eq(a, b)),
        (Value::Object(x), Value::Object(y)) => {
            x.len() == y.len() && x.iter().all(|(k, v)| y.get(k).is_some_and(|w| json_eq(v, w)))
        }
        _ => false,
    }
}

proptest! {
    #[test]
    fn proptest_matches_serde_json(value in json_value()) {
        let json = serde_json::to_string(&value).unwrap();
        let jiter: Value = from_str(&json).unwrap();
        let serde: Value = serde_json::from_str(&json).unwrap();
        prop_assert!(
            json_eq(&jiter, &serde),
            "mismatch for {json}\n  jiter: {jiter:?}\n  serde: {serde:?}"
        );
    }
}

//! Compare `jiter` with `serde_json` over the json-cases corpus: the two must agree on whether
//! each document is valid JSON and on the value it decodes to, bar the differences
//! [`known_difference`] lists. [`similar_cases_agree`] separately holds jiter to the corpus's
//! `similar` groups, one document spelled several ways: every member decodes to the same value, or
//! they are all rejected. See [`corpus`] for the checkout these need.
// floats are compared exactly on purpose, see `numbers_equal`
#![allow(clippy::float_cmp, clippy::print_stdout)]

use std::borrow::Cow;
use std::collections::HashMap;
use std::fmt;
use std::fmt::Write as _;

use jiter::JsonValue;
use serde_json::Value as SerdeValue;

mod corpus;

use corpus::{Loaded, corpus_root, load_cases};

/// How jiter and serde_json disagreed about one document.
#[derive(Debug)]
enum Mismatch {
    /// jiter parsed the document, serde_json rejected it
    JiterOnly { serde_error: String },
    /// serde_json parsed the document, jiter rejected it
    SerdeOnly { jiter_error: String },
    /// both parsed it, but into different values
    Value { detail: String },
    /// both rejected it, but with different errors
    Error { jiter_error: String, serde_error: String },
}

impl fmt::Display for Mismatch {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::JiterOnly { serde_error } => {
                write!(f, "jiter parsed it, serde_json returned an error: {serde_error:?}")
            }
            Self::SerdeOnly { jiter_error } => {
                write!(f, "serde_json parsed it, jiter returned an error: {jiter_error:?}")
            }
            Self::Value { detail } => write!(f, "both parsed it, {detail}"),
            Self::Error {
                jiter_error,
                serde_error,
            } => {
                write!(
                    f,
                    "both rejected it, jiter returned an error: {jiter_error:?}, serde_json returned an error: {serde_error:?}"
                )
            }
        }
    }
}

/// The ways jiter is known to differ from serde_json, and why; anything else is a test failure.
fn known_difference(mismatch: &Mismatch) -> Option<&'static str> {
    match mismatch {
        // jiter refuses integers and floats with more than 4300 digits, matching CPython's default
        // `sys.set_int_max_str_digits()`; serde_json (built with `arbitrary_precision` here) keeps
        // the raw token, so it has no such limit
        Mismatch::SerdeOnly { jiter_error } if starts_with_msg(jiter_error, "number out of range") => {
            Some("jiter caps numbers at 4300 digits, serde_json does not")
        }
        // jiter's recursion limit is 200, serde_json's default is 128, so documents nested between
        // the two are accepted by jiter alone, and documents that are also malformed hit one limit
        // or the other first
        Mismatch::JiterOnly { serde_error } if starts_with_msg(serde_error, "recursion limit exceeded") => {
            Some("jiter's recursion limit is 200, serde_json's is 128")
        }
        Mismatch::Error {
            jiter_error,
            serde_error,
        } if starts_with_msg(jiter_error, "recursion limit exceeded")
            || starts_with_msg(serde_error, "recursion limit exceeded") =>
        {
            Some("jiter's recursion limit is 200, serde_json's is 128")
        }
        // the two agree that the document is malformed and on why, but not on where: invalid
        // UTF-8 positions can differ in strings containing escapes, and the two count the start
        // of an invalid escape differently (pydantic/jiter#130)
        Mismatch::Error {
            jiter_error,
            serde_error,
        } if without_position(jiter_error) == without_position(serde_error)
            && matches!(
                without_position(jiter_error),
                "invalid unicode code point" | "invalid escape"
            ) =>
        {
            Some("same error, different position")
        }
        _ => None,
    }
}

/// Both parsers suffix their messages with ` at line N column M`; this is the message alone.
fn without_position(error: &str) -> &str {
    match error.find(" at line ") {
        Some(index) => &error[..index],
        None => error,
    }
}

fn starts_with_msg(error: &str, msg: &str) -> bool {
    without_position(error) == msg
}

/// Parse `json_data` with both parsers, returning how they disagreed, if they did.
fn compare(json_data: &[u8], allow_inf_nan: bool) -> Option<Mismatch> {
    match (
        JsonValue::parse(json_data, allow_inf_nan),
        serde_json::from_slice::<SerdeValue>(json_data),
    ) {
        (Ok(jiter_value), Ok(serde_value)) => {
            let mut path = String::new();
            let equal = values_equal(&jiter_value, &serde_value, &mut path);
            (!equal).then_some(Mismatch::Value { detail: path })
        }
        (Ok(_), Err(serde_error)) => Some(Mismatch::JiterOnly {
            serde_error: serde_error.to_string(),
        }),
        (Err(jiter_error), Ok(_)) => Some(Mismatch::SerdeOnly {
            jiter_error: jiter_error.description(json_data),
        }),
        (Err(jiter_error), Err(serde_error)) => {
            let jiter_error = jiter_error.description(json_data);
            let serde_error = serde_error.to_string();
            (jiter_error != serde_error).then_some(Mismatch::Error {
                jiter_error,
                serde_error,
            })
        }
    }
}

/// Compare a jiter value with a serde_json one, describing where they first differ in `detail`.
fn values_equal(jiter_value: &JsonValue, serde_value: &SerdeValue, detail: &mut String) -> bool {
    match (jiter_value, serde_value) {
        (JsonValue::Null, SerdeValue::Null) => true,
        (JsonValue::Bool(b1), SerdeValue::Bool(b2)) => b1 == b2,
        (JsonValue::Str(s1), SerdeValue::String(s2)) => s1 == s2,
        (JsonValue::Int(_) | JsonValue::Float(_), SerdeValue::Number(n)) => {
            numbers_equal(jiter_value, &n.to_string(), detail)
        }
        #[cfg(feature = "num-bigint")]
        (JsonValue::BigInt(_), SerdeValue::Number(n)) => numbers_equal(jiter_value, &n.to_string(), detail),
        (JsonValue::Array(a1), SerdeValue::Array(a2)) => {
            if a1.len() != a2.len() {
                let _ = write!(detail, "array has {} elements, serde_json got {}", a1.len(), a2.len());
                return false;
            }
            for (index, (v1, v2)) in a1.iter().zip(a2.iter()).enumerate() {
                if !values_equal(v1, v2, detail) {
                    detail.insert_str(0, &format!("[{index}]"));
                    return false;
                }
            }
            true
        }
        (JsonValue::Object(o1), SerdeValue::Object(o2)) => {
            let o1 = deduplicate(o1);
            if o1.len() != o2.len() {
                let _ = write!(detail, "object has {} keys, serde_json got {}", o1.len(), o2.len());
                return false;
            }
            for ((k1, v1), (k2, v2)) in o1.iter().zip(o2.iter()) {
                if k1 != k2 {
                    let _ = write!(detail, "key {k1:?}, serde_json got {k2:?}");
                    return false;
                }
                if !values_equal(v1, v2, detail) {
                    detail.insert_str(0, &format!("[{k1:?}]"));
                    return false;
                }
            }
            true
        }
        _ => {
            let _ = write!(detail, "{jiter_value:?}, serde_json got {serde_value:?}");
            false
        }
    }
}

/// The object's members with duplicate keys collapsed the way serde_json's map collapses them —
/// the first position a key appeared at, holding the last value given for it. jiter doesn't
/// deduplicate while parsing, it leaves that to the caller.
fn deduplicate<'a, 'j>(object: &'a [(Cow<'j, str>, JsonValue<'j>)]) -> Vec<(&'a str, &'a JsonValue<'j>)> {
    let mut positions: HashMap<&str, usize> = HashMap::with_capacity(object.len());
    let mut members: Vec<(&str, &JsonValue)> = Vec::with_capacity(object.len());
    for (key, value) in object {
        if let Some(&index) = positions.get(key.as_ref()) {
            members[index].1 = value;
        } else {
            positions.insert(key.as_ref(), members.len());
            members.push((key.as_ref(), value));
        }
    }
    members
}

/// serde_json is built with `arbitrary_precision` in this crate's dev-dependencies, so its numbers
/// are the raw token; compare jiter's decoded number with that token rather than with a second
/// lossy decode of it.
fn numbers_equal(jiter_value: &JsonValue, serde_number: &str, detail: &mut String) -> bool {
    let equal = match jiter_value {
        JsonValue::Int(i) => serde_number.parse::<i64>().is_ok_and(|s| s == *i),
        #[cfg(feature = "num-bigint")]
        JsonValue::BigInt(b) => serde_number.parse::<num_bigint::BigInt>().is_ok_and(|s| &s == b),
        // both decode with correct rounding, so this is exact rather than approximate
        JsonValue::Float(f) => serde_number.parse::<f64>().is_ok_and(|s| s == *f),
        _ => false,
    };
    if !equal {
        let _ = write!(detail, "{jiter_value:?}, serde_json got the token {serde_number}");
    }
    equal
}

/// Every case in the corpus, parsed by jiter and by serde_json, must give the same answer.
#[test]
fn compare_to_serde_json() {
    let Some(root) = corpus_root() else {
        return;
    };
    let mut unexpected: Vec<String> = Vec::new();
    let mut known: HashMap<&'static str, usize> = HashMap::new();
    let cases = load_cases(&root);
    for case in &cases {
        // `allow_inf_nan` is off so that jiter is asked for the same language serde_json parses;
        // `inf_nan_extension` below covers what turning it on adds
        if let Some(mismatch) = compare(&case.json_data, false) {
            match known_difference(&mismatch) {
                Some(reason) => *known.entry(reason).or_default() += 1,
                None => unexpected.push(format!("{}: {mismatch}", case.name)),
            }
        }
    }

    println!("{} cases", cases.len());
    let mut known: Vec<_> = known.into_iter().collect();
    known.sort_unstable();
    for (reason, count) in known {
        println!("  {count} known differences: {reason}");
    }
    assert!(
        unexpected.is_empty(),
        "{} of {} cases parsed differently by jiter and serde_json:\n{}",
        unexpected.len(),
        cases.len(),
        unexpected.join("\n")
    );
}

/// With `allow_inf_nan` jiter also accepts the `NaN`/`Infinity` documents CPython's `json` module
/// writes and reads, which are not JSON — the one place jiter deliberately parses more than
/// serde_json does. It must add nothing else: everything serde_json accepts must still parse to
/// the same value.
#[test]
fn inf_nan_extension() {
    let Some(root) = corpus_root() else {
        return;
    };
    let mut extra: Vec<String> = Vec::new();
    let mut unexpected: Vec<String> = Vec::new();
    let cases = load_cases(&root);
    let inf_nan = cases.iter().filter(|case| case.category == "python-inf-nan");
    for case in inf_nan {
        match compare(&case.json_data, true) {
            Some(Mismatch::JiterOnly { .. }) => {
                // the only documents jiter may accept and serde_json reject are the ones this
                // directory exists for
                let text = String::from_utf8_lossy(&case.json_data);
                assert!(
                    text.contains("NaN") || text.contains("Infinity"),
                    "{}: accepted with allow_inf_nan but holds no NaN/Infinity",
                    case.name
                );
                extra.push(case.name.clone());
            }
            // both rejected it: jiter reads further into a malformed `NaN`/`Infinity` token
            // before giving up than serde_json does, so only the verdict has to agree here
            Some(Mismatch::Error { .. }) | None => (),
            // jiter must not reject, or decode differently, anything serde_json accepts, unless
            // it is one of the differences the corpus-wide test already allows
            Some(mismatch) if known_difference(&mismatch).is_none() => {
                unexpected.push(format!("{}: {mismatch}", case.name));
            }
            Some(_) => (),
        }
    }

    assert!(unexpected.is_empty(), "{}", unexpected.join("\n"));
    assert!(
        !extra.is_empty(),
        "no NaN/Infinity documents were accepted, is the corpus complete?"
    );
    println!("{} NaN/Infinity documents accepted with allow_inf_nan", extra.len());
}

/// Compare two values jiter decoded, describing where they first differ in `detail`. Members of a
/// group hold the same numbers written the same way and the same keys in the same order, so this
/// is exact, structural equality; `NaN`, which is not equal to itself, is the one special case.
fn jiter_values_equal(v1: &JsonValue, v2: &JsonValue, detail: &mut String) -> bool {
    match (v1, v2) {
        (JsonValue::Float(f1), JsonValue::Float(f2)) if f1.is_nan() && f2.is_nan() => true,
        (JsonValue::Array(a1), JsonValue::Array(a2)) => {
            if a1.len() != a2.len() {
                let _ = write!(detail, "array has {} elements, the other has {}", a1.len(), a2.len());
                return false;
            }
            for (index, (e1, e2)) in a1.iter().zip(a2.iter()).enumerate() {
                if !jiter_values_equal(e1, e2, detail) {
                    detail.insert_str(0, &format!("[{index}]"));
                    return false;
                }
            }
            true
        }
        // jiter doesn't deduplicate keys, and neither does the corpus: a group repeats the same
        // key the same number of times, so the members are compared as written
        (JsonValue::Object(o1), JsonValue::Object(o2)) => {
            if o1.len() != o2.len() {
                let _ = write!(detail, "object has {} keys, the other has {}", o1.len(), o2.len());
                return false;
            }
            for ((k1, e1), (k2, e2)) in o1.iter().zip(o2.iter()) {
                if k1 != k2 {
                    let _ = write!(detail, "key {k1:?}, the other has {k2:?}");
                    return false;
                }
                if !jiter_values_equal(e1, e2, detail) {
                    detail.insert_str(0, &format!("[{k1:?}]"));
                    return false;
                }
            }
            true
        }
        _ => {
            if v1 == v2 {
                return true;
            }
            let _ = write!(detail, "{v1:?}, the other has {v2:?}");
            false
        }
    }
}

/// The members of a `similar` group are one document written several ways — re-indented, or with
/// its strings escaped differently — so jiter must decode them all to the same value, or, where
/// the document is malformed, reject them all. Only *where* the error is reported may vary within
/// a rejected group, the spellings put the same mistake in different places.
#[test]
fn similar_cases_agree() {
    let Some(root) = corpus_root() else {
        return;
    };
    let cases = load_cases(&root);
    let by_name: HashMap<&str, &Loaded> = cases.iter().map(|case| (case.name.as_str(), case)).collect();
    let mut failures: Vec<String> = Vec::new();
    let mut groups = 0;
    let mut documents = 0;

    for case in cases.iter().filter(|case| !case.similar.is_empty()) {
        groups += 1;
        documents += case.similar.len() + 1;
        // what a group promises is a property of the document, not of how jiter is configured, so
        // it has to hold either way; `allow_inf_nan` is also what makes the `python-inf-nan`
        // groups compare values at all rather than agree on rejecting them
        for allow_inf_nan in [false, true] {
            let first = JsonValue::parse(&case.json_data, allow_inf_nan);
            for name in &case.similar {
                let other = by_name
                    .get(name.as_str())
                    .unwrap_or_else(|| panic!("{name}: listed as similar but missing from cases.json"));
                match (&first, JsonValue::parse(&other.json_data, allow_inf_nan)) {
                    (Ok(value), Ok(other_value)) => {
                        let mut detail = String::new();
                        if !jiter_values_equal(value, &other_value, &mut detail) {
                            failures.push(format!(
                                "{} and {} (allow_inf_nan={allow_inf_nan}) decoded differently: {detail}",
                                case.name, other.name
                            ));
                        }
                    }
                    // both rejected, which is all a group of malformed documents promises
                    (Err(_), Err(_)) => (),
                    (Ok(_), Err(error)) => failures.push(format!(
                        "{} parsed (allow_inf_nan={allow_inf_nan}), {} was rejected: {}",
                        case.name,
                        other.name,
                        error.description(&other.json_data)
                    )),
                    (Err(error), Ok(_)) => failures.push(format!(
                        "{} was rejected (allow_inf_nan={allow_inf_nan}): {}, {} parsed",
                        case.name,
                        error.description(&case.json_data),
                        other.name
                    )),
                }
            }
        }
    }

    assert!(
        groups > 0,
        "cases.json holds no `similar` groups, is the corpus complete?"
    );
    assert!(
        failures.is_empty(),
        "{} comparisons across {groups} similar groups disagreed:\n{}",
        failures.len(),
        failures.join("\n")
    );
    println!("{groups} similar groups, {documents} documents");
}

//! Loading the [`json-cases`](https://github.com/samuelcolvin/json-cases) corpus, shared by the
//! `json_cases` test and benchmark. `cases/` is a build artifact, so a checkout has to be built
//! with `make build`; `../json-cases` is used by default, `JSON_CASES` overrides it. The tests
//! require it, failing rather than skipping when it is absent so a checkout without it can't
//! quietly pass; `JSON_CASES_SKIP` opts out, as CI does where building it isn't worth it.
#![allow(dead_code, clippy::print_stdout)]

use std::path::{Path, PathBuf};

use serde::Deserialize;

/// One entry of `cases.json`. The index also records the error serde_json gave when it was
/// written; that is ignored here, the test runs its own copy of serde_json instead.
#[derive(Deserialize)]
struct Case {
    /// absolute path, valid only in the checkout that generated the index
    path: String,
    /// the top level directory under `cases/`
    category: String,
    /// what the document is made of, see [`TAGS`]
    #[serde(default)]
    tags: Vec<String>,
    /// the other files holding this same document in a different spelling, recorded on one member
    /// of each group so that following it from every entry visits each group once
    #[serde(default)]
    similar: Vec<String>,
}

/// A case with its content read, and its paths re-rooted at this checkout.
pub struct Loaded {
    /// path relative to the corpus root, doubling as the name to report the case by
    pub name: String,
    pub json_data: Vec<u8>,
    pub category: String,
    /// what the document is made of, see [`TAGS`]
    pub tags: Vec<String>,
    /// the `name`s of the other members of this case's group, see [`Case::similar`]
    pub similar: Vec<String>,
}

/// The `json-cases` checkout, or `None` if it hasn't been cloned and built.
pub fn find_corpus_root() -> Option<PathBuf> {
    let root = match std::env::var_os("JSON_CASES") {
        Some(dir) => PathBuf::from(dir),
        None => Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../json-cases"),
    };
    root.join("cases.json").is_file().then_some(root)
}

/// The `json-cases` checkout to run the tests over, or `None` if `JSON_CASES_SKIP` is set to
/// something non-empty; without it a missing corpus panics rather than skipping.
pub fn corpus_root() -> Option<PathBuf> {
    if std::env::var_os("JSON_CASES_SKIP").is_some_and(|skip| !skip.is_empty()) {
        println!("JSON_CASES_SKIP is set, skipping");
        return None;
    }
    Some(find_corpus_root().unwrap_or_else(|| {
        panic!(
            "the json-cases corpus is missing, the tests need it:\n\
             \x20   git clone https://github.com/samuelcolvin/json-cases ../json-cases\n\
             \x20   make -C ../json-cases build\n\
             or point JSON_CASES at an existing checkout; `cases.json` was looked for under {}",
            std::env::var_os("JSON_CASES").map_or_else(
                || "../json-cases, next to this repository".to_string(),
                |dir| dir.to_string_lossy().into_owned()
            )
        )
    }))
}

/// `cases.json` holds absolute paths, valid only in the checkout that generated it, so re-root
/// them; the result doubles as the name to report a case by.
fn relative(root: &Path, path: &str) -> String {
    if let Ok(rel) = Path::new(path).strip_prefix(root) {
        return rel.to_string_lossy().into_owned();
    }
    match path.find("/cases/") {
        Some(index) => path[index + 1..].to_string(),
        None => path.to_string(),
    }
}

/// Every case in the index, with its content read into memory.
pub fn load_cases(root: &Path) -> Vec<Loaded> {
    let index = std::fs::read(root.join("cases.json")).unwrap();
    let cases: Vec<Case> = serde_json::from_slice(&index).unwrap();
    assert!(!cases.is_empty(), "cases.json is empty, run `make build` in the corpus");
    cases
        .into_iter()
        .map(|case| {
            let name = relative(root, &case.path);
            let json_data = std::fs::read(root.join(&name))
                .unwrap_or_else(|e| panic!("{name}: {e}, run `make build` in the corpus"));
            let similar = case.similar.iter().map(|path| relative(root, path)).collect();
            Loaded {
                name,
                json_data,
                category: case.category,
                tags: case.tags,
                similar,
            }
        })
        .collect()
}

/// The `tags` the index uses, in the order the benchmark reports them.
///
/// A tag names a lexical class that holds at least a quarter of the document's bytes — a tenth of
/// its *string* bytes for `escapes` and `non-ascii`, since the escape-free fast path is a fork
/// inside the string scanner rather than a share of the file — so it says what a parser would
/// spend its time on rather than what the document merely contains. `deep` is nesting of 20
/// levels or more, and `error` is a verdict rather than a shape: no conforming parser accepts the
/// document. Documents carry several, and `cases.json` describes them in full.
pub const TAGS: [&str; 12] = [
    "strings",
    "escapes",
    "non-ascii",
    "numbers",
    "ints",
    "floats",
    "constants",
    "arrays",
    "objects",
    "deep",
    "whitespace",
    "error",
];

use std::sync::{Mutex, MutexGuard, PoisonError};

use ahash::random_state::RandomState;
use pyo3::exceptions::{PyTypeError, PyValueError};
use pyo3::prelude::*;
use pyo3::types::{PyBool, PyString};
use smallvec::SmallVec;

use crate::string_decoder::StringOutput;

#[derive(Debug, Clone, Copy, Default)]
pub enum StringCacheMode {
    #[default]
    All,
    Keys,
    None,
}

impl<'py> FromPyObject<'_, 'py> for StringCacheMode {
    type Error = PyErr;

    fn extract(ob: Borrowed<'_, 'py, PyAny>) -> PyResult<StringCacheMode> {
        if let Ok(bool_mode) = ob.cast::<PyBool>() {
            Ok(bool_mode.is_true().into())
        } else if let Ok(str_mode) = ob.extract::<&str>() {
            match str_mode {
                "all" => Ok(Self::All),
                "keys" => Ok(Self::Keys),
                "none" => Ok(Self::None),
                _ => Err(PyValueError::new_err(
                    "Invalid string cache mode, should be `'all'`, '`keys`', `'none`' or a `bool`",
                )),
            }
        } else {
            Err(PyTypeError::new_err(
                "Invalid string cache mode, should be `'all'`, '`keys`', `'none`' or a `bool`",
            ))
        }
    }
}

impl From<bool> for StringCacheMode {
    fn from(mode: bool) -> Self {
        if mode { Self::All } else { Self::None }
    }
}

/// The string cache a parse works on, taken from the pool on the first cacheable string and
/// returned to it when the parse ends.
#[derive(Default)]
pub(crate) struct StringCacheGuard(Option<PyStringCache>);

impl Drop for StringCacheGuard {
    fn drop(&mut self) {
        if let Some(cache) = self.0.take() {
            return_string_cache(cache);
        }
    }
}

pub trait StringMaybeCache {
    fn get_key<'py>(
        py: Python<'py>,
        guard: &mut StringCacheGuard,
        string_output: StringOutput<'_, '_>,
    ) -> Bound<'py, PyString>;

    fn get_value<'py>(
        py: Python<'py>,
        guard: &mut StringCacheGuard,
        string_output: StringOutput<'_, '_>,
    ) -> Bound<'py, PyString> {
        Self::get_key(py, guard, string_output)
    }
}

/// # Safety
///
/// Caller must match the ascii_only flag to the string passed in.
#[inline]
unsafe fn guarded_py_string<'py>(
    py: Python<'py>,
    guard: &mut StringCacheGuard,
    string_output: &StringOutput<'_, '_>,
) -> Bound<'py, PyString> {
    let s = string_output.as_str();
    let ascii_only = string_output.ascii_only();
    if (2..64).contains(&s.len()) {
        let cache = guard.0.get_or_insert_with(take_string_cache);
        unsafe { cache.get_or_insert(py, s, ascii_only) }
    } else {
        unsafe { pystring_fast_new_maybe_ascii(py, s, ascii_only) }
    }
}

